  COALESCE((item->>'created_at')::timestamptz, now()),
  COALESCE((item->>'updated_at')::timestamptz, now())
FROM jsonb_array_elements($letters$[{"id":"letter-26-01","doc_number":"ALK Technology - Construction Safety - 26-01호","direction":"발신","dispatch_date":"2026. 07. 24.","recipient":"각 사 대표이사","reference":"에어리퀴드코리아 기술본부 CM팀, 건설안전팀","sender":"에어리퀴드코리아 기술본부 건설안전팀 박서로 차장","sender_department":"에어리퀴드코리아 기술본부 건설안전팀","sender_title":"차장","sender_name":"박 서 로","subject":"GSC 여수 H2/LCO2 PJT 「안전의 날」 행사 참석 요청의 件","content_paragraphs":["귀 사의 무궁한 발전과 건설 현장의 무재해를 기원합니다.","당사는 근로자 안전 의식 제고를 위해 기술본부 이용상 부사장님 주관하에 매 3개월마다 「안전의 날」 행사를 개최하고 있습니다.","바쁘시더라도 각 사 대표이사님(부득이한 경우 임원급 대체)의 참석을 부탁드립니다. 아울러, 당일 오전에는 대표이사님 주관하에 자체적인 현장 점검을 실시해 주시기를 당부드립니다."],"sub_items_title":"- 아 래 -","sub_items":[{"label":"가. 일 정","text":"2026년 7월 30일(목)","sub_bullets":["12:00 ~ 13:10 : 당사 임직원 오찬 (점심 식사)","13:30 ~ 14:00 : 안전의 날 본 행사","14:00 ~ : 임직원 간담회"]},{"label":"나. 장 소","text":"GSC 여수 H2/LCO2 PJT 현장 안전조회장"}],"status":"발송완료","attachments":"행사 식순 및 참석자 명단 양식 1부","notes":"에어리퀴드 기술본부 공식 공문 1호 발송 건","created_at":"2026-07-24T09:00:00Z","updated_at":"2026-07-24T14:30:00Z"},{"id":"letter-26-02","doc_number":"ALK Technology - Construction Safety - 26-02호","direction":"발신","dispatch_date":"2026. 08. 10.","recipient":"원청 및 전 협력사 현장소장","reference":"에어리퀴드코리아 기술본부 CM팀","sender":"에어리퀴드코리아 기술본부 건설안전팀 박서로 차장","sender_department":"에어리퀴드코리아 기술본부 건설안전팀","sender_title":"차장","sender_name":"박 서 로","subject":"하절기 옥외 근로자 온열질환 예방 3대 기본수칙 이행 및 자체 점검의 件","content_paragraphs":["귀 사의 무궁한 발전과 현장 무재해를 기원합니다.","폭염 특보 발령에 따라 산업안전보건기준에 관한 규칙 제566조에 의거하여 옥외 근로자 건강보호 조치를 철저히 이행하여 주시기 바랍니다.","각 사 현장소장님께서는 물, 그늘, 휴식 3대 수칙 준수 여부를 일일 점검하고 그 결과를 건설안전팀에 제출해 주시기 바랍니다."],"sub_items_title":"- 아 래 -","sub_items":[{"label":"가. 주요 점검 사항","text":"휴게시설 냉방장치 가동 및 얼음물/식염정 비치 여부","sub_bullets":["폭염 체감온도 33℃ 이상 시 시간당 10~15분 휴식 부여","단독 작업 지양 및 온열질환 민감군 일일 건강문진"]},{"label":"나. 점검 결과 제출","text":"매주 금요일 17:00까지 건설안전팀 담당자 이메일 송부"}],"status":"발송완료","created_at":"2026-08-10T10:00:00Z","updated_at":"2026-08-10T11:00:00Z"},{"id":"letter-rec-26-01","doc_number":"ALK-REC-26-01호","direction":"수신","dispatch_date":"2026. 08. 03.","received_at":"2026. 08. 03.","original_doc_number":"고용노동부여수-산안-2026-482호","sender_organization":"고용노동부 여수지청 산재예방지도과","recipient":"에어리퀴드코리아(유) 대표이사 / 현장소장","reference":"건설안전팀","sender":"고용노동부 여수지청장","subject":"2026년 하절기 플랜트 건설현장 취약시기 산업안전 감독 계획 통보 및 자체점검 요청의 件","handling_assignee":"박서로 차장","handling_due_date":"2026-08-18","handling_status":"처리완료","status":"처리완료","action_taken":"원청 및 협력사 합동 자체점검 실시 완료, 온열질환 대책 수립 후 ALK Technology - Construction Safety - 26-02호로 현장 배포 및 관할 관청 점검표 제출 완료","reply_doc_number":"ALK Technology - Construction Safety - 26-02호","attachment_name":"하절기_건설현장_안전보건_자체점검표.pdf","notes":"노동청 감독관 현장 입회 점검 완료(특이 지적사항 없음)","created_at":"2026-08-03T11:00:00Z","updated_at":"2026-08-15T16:00:00Z"},{"id":"letter-rec-26-02","doc_number":"ALK-REC-26-02호","direction":"수신","dispatch_date":"2026. 08. 12.","received_at":"2026. 08. 12.","original_doc_number":"현대E&C-여수-안전-26-89호","sender_organization":"현대엔지니어링(주) 여수 현장단","recipient":"에어리퀴드코리아 기술본부 건설안전팀","reference":"기술본부 CM팀","sender":"현대엔지니어링(주) 여수 H2/LCO2 현장소장","subject":"대형 크레인(100톤 하이드로) 진입에 따른 현장 지반 지지력 검토서 및 양중계획서 제출의 件","handling_assignee":"박서로 차장","handling_due_date":"2026-11-11","handling_status":"조치/회신중","status":"조치중","action_taken":"지반 지지력 계산서 구조기술사 검토 확인 중, 아웃트리거 철판 보강 규격 현장 실사 예정","attachment_name":"100톤_크레인_양중계획서_및_지반검토서.pdf","notes":"8월 18일 양중 작업 전 발주처 최종 승인 회신 필요","created_at":"2026-08-12T14:30:00Z","updated_at":"2026-08-12T14:30:00Z"}]$letters$::jsonb) AS item
